import React, { useEffect, useState } from 'react';
import getVotingContract from '../utils/getVotingContract';

const VotingPage = () => {
  const [candidates, setCandidates] = useState([]);
  const [hasVoted, setHasVoted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [votedCandidateIndex, setVotedCandidateIndex] = useState(null);

  const [account, setAccount] = useState("");

  useEffect(() => {
    const init = async () => {
      const contract = await getVotingContract();
  
      const accounts = await window.ethereum.request({ method: "eth_requestAccounts" });
      const userAccount = accounts[0];
      setAccount(userAccount);
  
      const voted = await contract.hasVoted(userAccount);
      setHasVoted(voted);
  
      const candidateCount = await contract.getCandidateCount();
      const tempCandidates = [];
  
      let votedIndex = null;
  
      for (let i = 0; i < candidateCount; i++) {
        const name = await contract.getCandidateName(i);
        const votes = await contract.getVoteCount(i);
        tempCandidates.push({ name, votes });
  
        // 💡 Optional: try to find the one user voted for
        // This assumes each user can vote once and vote count went up by 1.
        if (voted && votes > 0 && votedIndex === null) {
          votedIndex = i;
        }
      }
  
      if (votedIndex !== null) setVotedCandidateIndex(votedIndex);
  
      setCandidates(tempCandidates);
      setLoading(false);
    };
  
    init();
  }, []);
  

  const handleVote = async (index) => {
    try {
      const contract = await getVotingContract();
      await contract.vote(index);
      setHasVoted(true);
    setVotedCandidateIndex(index);  // Set local state

      // Update vote count
      const updatedCandidates = [...candidates];
      updatedCandidates[index].votes += 1;
      setCandidates(updatedCandidates);

    } catch (err) {
      console.error("Voting error:", err);
    }
  };

  if (loading) return <div>Loading candidates...</div>;

  return (
    <div className="container mt-4">
      <h2 className="mb-4">Vote for Your Candidate</h2>
      <table className="table table-bordered">
        <thead className="thead-dark">
          <tr>
            <th>#</th>
            <th>Name</th>
            <th>Votes</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {candidates.map((candidate, index) => (
            <tr key={index}>
              <td>{index + 1}</td>
              <td>{candidate.name}</td>
              <td>{candidate.votes}</td>
              <td>
                {hasVoted ? (
                  <button className="btn btn-secondary" disabled>Voted</button>
                ) : (
                  <button className="btn btn-success" onClick={() => handleVote(index)}>Vote</button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default VotingPage;
